const OPT_OUT = /^(pare|parar|para de (mandar|enviar)|sair|stop|descadastr|remover?( meu)?|me tira|n[aã]o (quero|me) (mais|mand|envi)|nunca mais me)/i;

function paraE164(entrada) {
  let d = String(entrada || '').replace(/\D/g, '');
  if (!d) return null;
  if (d.startsWith('55') && d.length === 12) {
    const ddd = d.slice(2, 4);
    const local = d.slice(4);
    if (/^[6-9]/.test(local)) d = '55' + ddd + '9' + local;
  }
  if (d.length < 8 || d.length > 15) return null;
  if (d[0] === '0') return null;
  return '+' + d;
}

function desembrulhar(msg, nivel) {
  nivel = nivel || 0;
  if (!msg || nivel > 5) return msg || {};
  if (msg.ephemeralMessage) return desembrulhar(msg.ephemeralMessage.message, nivel + 1);
  if (msg.viewOnceMessage) return desembrulhar(msg.viewOnceMessage.message, nivel + 1);
  if (msg.viewOnceMessageV2) return desembrulhar(msg.viewOnceMessageV2.message, nivel + 1);
  if (msg.viewOnceMessageV2Extension) return desembrulhar(msg.viewOnceMessageV2Extension.message, nivel + 1);
  if (msg.documentWithCaptionMessage) return desembrulhar(msg.documentWithCaptionMessage.message, nivel + 1);
  if (msg.editedMessage) return desembrulhar(msg.editedMessage.message, nivel + 1);
  return msg;
}

function extrairTexto(bruta) {
  const m = desembrulhar(bruta);
  if (!m || typeof m !== 'object') return null;
  if (typeof m.conversation === 'string' && m.conversation.trim()) {
    return { texto: m.conversation, tipo: 'texto' };
  }
  if (m.extendedTextMessage && m.extendedTextMessage.text) {
    return { texto: m.extendedTextMessage.text, tipo: 'texto' };
  }
  if (m.imageMessage) {
    return { texto: m.imageMessage.caption || '[imagem]', tipo: 'imagem' };
  }
  if (m.videoMessage) {
    return { texto: m.videoMessage.caption || '[video]', tipo: 'video' };
  }
  if (m.documentMessage) {
    const arq = m.documentMessage.fileName ? ' ' + m.documentMessage.fileName : '';
    return { texto: m.documentMessage.caption || ('[documento' + arq + ']'), tipo: 'documento' };
  }
  if (m.audioMessage) return { texto: '[audio]', tipo: 'audio' };
  if (m.stickerMessage) return { texto: '[figurinha]', tipo: 'figurinha' };
  if (m.contactMessage || m.contactsArrayMessage) return { texto: '[contato]', tipo: 'contato' };
  if (m.locationMessage || m.liveLocationMessage) {
    return { texto: '[localizacao]', tipo: 'localizacao' };
  }
  if (m.buttonsResponseMessage && m.buttonsResponseMessage.selectedDisplayText) {
    return { texto: m.buttonsResponseMessage.selectedDisplayText, tipo: 'texto' };
  }
  if (m.templateButtonReplyMessage && m.templateButtonReplyMessage.selectedDisplayText) {
    return { texto: m.templateButtonReplyMessage.selectedDisplayText, tipo: 'texto' };
  }
  if (m.listResponseMessage && m.listResponseMessage.singleSelectReply) {
    const t = m.listResponseMessage.title || m.listResponseMessage.singleSelectReply.selectedRowId;
    if (t) return { texto: t, tipo: 'texto' };
  }
  return null;
}

function paraIso(valor) {
  if (valor === null || valor === undefined) return new Date().toISOString();
  const s = String(valor);
  if (/^\d+$/.test(s)) {
    const n = Number(s);
    const ms = n > 1e12 ? n : n * 1000;
    const dt = new Date(ms);
    return isNaN(dt.getTime()) ? new Date().toISOString() : dt.toISOString();
  }
  const dt = new Date(s);
  return isNaN(dt.getTime()) ? new Date().toISOString() : dt.toISOString();
}

function descartar(motivo, extra) {
  return { json: Object.assign({ ignorar: true, motivo_ignorado: motivo }, extra || {}) };
}

const saida = [];

for (const item of $input.all()) {
  const corpo = item.json.body || item.json;
  const evento = String(corpo.event || '').toLowerCase().replace(/_/g, '.');
  const instancia = corpo.instance || corpo.instanceId || null;

  if (evento && evento !== 'messages.upsert') {
    saida.push(descartar('evento nao tratado: ' + evento, { evento: evento }));
    continue;
  }

  const bruto = corpo.data !== undefined ? corpo.data : null;
  const lista = Array.isArray(bruto) ? bruto : bruto ? [bruto] : [];
  if (lista.length === 0) {
    saida.push(descartar('payload sem data', { evento: evento }));
    continue;
  }

  for (const d of lista) {
    const chave = d.key || {};
    const jidBruto = String(chave.remoteJid || '');

    if (!jidBruto) {
      saida.push(descartar('mensagem sem remoteJid'));
      continue;
    }
    if (jidBruto.endsWith('@g.us')) {
      saida.push(descartar('mensagem de grupo', { jid: jidBruto }));
      continue;
    }
    if (jidBruto.includes('broadcast') || jidBruto.endsWith('@newsletter')) {
      saida.push(descartar('status ou canal', { jid: jidBruto }));
      continue;
    }

    let jidPessoa = jidBruto;
    if (jidBruto.endsWith('@lid')) {
      const alt = chave.remoteJidAlt || chave.senderPn || d.remoteJidAlt || '';
      if (!alt) {
        saida.push(descartar('jid @lid sem numero real', { jid: jidBruto }));
        continue;
      }
      jidPessoa = String(alt);
    }

    const telefone = paraE164(jidPessoa.split('@')[0].split(':')[0]);
    if (!telefone) {
      saida.push(descartar('telefone invalido', { jid: jidBruto }));
      continue;
    }

    const conteudo = extrairTexto(d.message);
    if (!conteudo) {
      saida.push(descartar('mensagem sem conteudo aproveitavel', { jid: jidBruto }));
      continue;
    }

    const daEquipe = chave.fromMe === true;
    const texto = String(conteudo.texto).slice(0, 4000);
    const limpo = texto.trim();

    saida.push({
      json: {
        ignorar: false,
        motivo_ignorado: '',
        telefone: telefone,
        nome: daEquipe ? '' : String(d.pushName || '').slice(0, 120),
        direcao: daEquipe ? 'equipe' : 'lead',
        texto: texto,
        tipo_midia: conteudo.tipo,
        enviada_em: paraIso(d.messageTimestamp),
        evolution_msg_id: chave.id ? String(chave.id) : '',
        opt_out: !daEquipe && limpo.length <= 60 && OPT_OUT.test(limpo),
        instancia: instancia,
      },
    });
  }
}

return saida;
